definicion.css:
.sofia-gen--hero_diagonal { position: relative; width: 100%; overflow: hidden; }
.sofia-gen--hero_diagonal .sg-hero-contenedor { position: relative; height: clamp(400px, 70vh, 700px); display: flex; align-items: center; justify-content: center; overflow: hidden; }
.sofia-gen--hero_diagonal .sg-hero-imagen-wrapper { position: absolute; top: 0; left: 0; width: 100%; height: 100%; clip-path: polygon(0 0, 100% 0, 100% 85%, 0% 100%); background-color: #000; }
.sofia-gen--hero_diagonal .sg-hero-imagen { width: 100%; height: 100%; object-fit: cover; opacity: 0.7; }
.sofia-gen--hero_diagonal .sg-hero-overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: linear-gradient(to bottom, rgba(0,0,0,0.3) 0%, rgba(0,0,0,0.7) 100%); }
.sofia-gen--hero_diagonal .sg-hero-titulo { position: relative; z-index: 1; color: #fff; text-align: center; font-size: clamp(2.5rem, 8vw, 5rem); line-height: 1.1; max-width: 90%; text-shadow: 2px 2px 8px rgba(0,0,0,0.7); }

.sofia-gen--seccion_onda_inferior { padding: clamp(4rem, 10vh, 8rem) 0; position: relative; overflow: hidden; }
.sofia-gen--seccion_onda_inferior .sg-seccion-onda { position: relative; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; color: white; min-height: 50vh; }
.sofia-gen--seccion_onda_inferior .sg-imagen-fondo { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; z-index: -2; filter: brightness(0.5); }
.sofia-gen--seccion_onda_inferior .sg-contenido { position: relative; z-index: 1; padding: 0 clamp(1rem, 5vw, 4rem); max-width: 900px; }
.sofia-gen--seccion_onda_inferior .sg-titulo-seccion { font-size: clamp(2rem, 6vw, 4rem); margin-bottom: 1rem; line-height: 1.2; font-weight: 700; text-shadow: 2px 2px 8px rgba(0,0,0,0.4); }
.sofia-gen--seccion_onda_inferior .sg-subtitulo-seccion { font-size: clamp(1rem, 2.5vw, 1.5rem); line-height: 1.6; max-width: 700px; opacity: 0.9; text-shadow: 1px 1px 6px rgba(0,0,0,0.3); }
.sofia-gen--seccion_onda_inferior .sg-seccion-onda::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 15%; background: linear-gradient(to top, rgba(var(--wp--preset--color--foreground), 1) 0%, rgba(var(--wp--preset--color--foreground), 0) 100%); clip-path: ellipse(100% 50% at 50% 100%); z-index: -1; background-color: var(--wp--preset--color--background); }

.sofia-gen--tarjeta_esquina_doblada { display: flex; justify-content: center; align-items: center; padding: 2rem; min-height: 200px; background-color: #f0f2f5; }
.sofia-gen--tarjeta_esquina_doblada .sg-tarjeta-contenedor { position: relative; width: clamp(280px, 80vw, 400px); min-height: 220px; background-color: #ffffff; border-radius: 8px; box-shadow: 0 10px 20px rgba(0,0,0,0.1), 0 6px 6px rgba(0,0,0,0.05); padding: 25px; overflow: hidden; display: flex; flex-direction: column; justify-content: flex-start; align-items: flex-start; text-align: left; transition: transform 0.3s ease; }
.sofia-gen--tarjeta_esquina_doblada .sg-tarjeta-contenedor:hover { transform: translateY(-5px); }
.sofia-gen--tarjeta_esquina_doblada .sg-tarjeta-plegada { position: absolute; top: 0; right: 0; width: 0; height: 0; border-style: solid; border-width: 0 40px 40px 0; border-color: transparent #e0e0e0 transparent transparent; box-shadow: -2px 2px 3px rgba(0,0,0,0.15); transform: rotate(90deg); transform-origin: top right; }
.sofia-gen--tarjeta_esquina_doblada .sg-tarjeta-titulo { font-size: clamp(1.4rem, 5vw, 1.8rem); color: #333; margin-bottom: 0.8rem; line-height: 1.2; font-weight: 700; }
.sofia-gen--tarjeta_esquina_doblada .sg-tarjeta-descripcion { font-size: clamp(0.95rem, 4vw, 1.1rem); color: #555; line-height: 1.6; margin-top: 0; }

.sofia-gen--tarjeta_precio_vidrio { display: flex; justify-content: center; align-items: center; min-height: 400px; padding: 20px; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-precio { background: rgba(255, 255, 255, 0.15); backdrop-filter: blur(10px); border-radius: 15px; border: 1px solid rgba(255, 255, 255, 0.2); padding: clamp(20px, 5vw, 40px); text-align: center; color: #fff; box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37); max-width: 350px; display: flex; flex-direction: column; gap: 15px; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-titulo { font-size: clamp(1.8rem, 4vw, 2.5rem); margin-bottom: 10px; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-precio-valor { font-size: clamp(2.5rem, 6vw, 4rem); font-weight: bold; margin-bottom: 15px; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-descripcion { font-size: clamp(0.9rem, 2vw, 1.1rem); line-height: 1.5; margin-bottom: 20px; }
.sofia-gen--tarjeta_precio_vidrio .sg-lista-caracteristicas { list-style: none; padding: 0; margin-bottom: 25px; text-align: left; align-self: flex-start; width: 100%; }
.sofia-gen--tarjeta_precio_vidrio .sg-caracteristica-item { font-size: clamp(0.9rem, 2vw, 1rem); margin-bottom: 8px; padding-left: 25px; position: relative; }
.sofia-gen--tarjeta_precio_vidrio .sg-caracteristica-item::before { content: '✓'; color: #8aff8a; position: absolute; left: 0; top: 0; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-boton { background: rgba(255, 255, 255, 0.3); border: none; border-radius: 8px; padding: 12px 25px; font-size: clamp(1rem, 2vw, 1.2rem); font-weight: bold; cursor: pointer; transition: background 0.3s ease; align-self: center; }
.sofia-gen--tarjeta_precio_vidrio .sg-tarjeta-boton:hover { background: rgba(255, 255, 255, 0.5); }

.sofia-gen--imagen_sobresaliente { padding: clamp(2rem, 5vw, 4rem) 0; overflow: hidden; background-color: #f8f8f8; }
.sofia-gen--imagen_sobresaliente .sg-contenedor-seccion { display: grid; grid-template-columns: minmax(min(20rem, 100%), 1fr) clamp(25rem, 50vw, 40rem); gap: clamp(2rem, 5vw, 4rem); align-items: center; max-width: 1400px; margin: 0 auto; padding: 0 clamp(1rem, 5vw, 2rem); }
.sofia-gen--imagen_sobresaliente .sg-contenido-texto { padding-right: clamp(1rem, 3vw, 2rem); }
.sofia-gen--imagen_sobresaliente .sg-titulo { font-size: clamp(2rem, 5vw, 3.5rem); color: #333; line-height: 1.1; margin-bottom: 1rem; }
.sofia-gen--imagen_sobresaliente .sg-descripcion { font-size: clamp(1rem, 2.5vw, 1.25rem); color: #666; line-height: 1.6; }
.sofia-gen--imagen_sobresaliente .sg-contenedor-imagen { position: relative; width: 100%; height: 0; padding-bottom: 75%; overflow: visible; margin-right: -20%; }
.sofia-gen--imagen_sobresaliente .sg-imagen { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; border-radius: 8px; box-shadow: 0 15px 30px rgba(0, 0, 0, 0.2); }
.sofia-gen--imagen_sobresaliente .sg-contenedor-seccion { grid-template-columns: 1fr; }
.sofia-gen--imagen_sobresaliente .sg-contenedor-imagen { margin-right: 0; margin-top: 2rem; padding-bottom: 60%; }
.sofia-gen--imagen_sobresaliente .sg-contenido-texto { padding-right: 0; text-align: center; }

.sofia-gen--tarjetas_superpuestas { padding: 4rem 1rem; display: flex; justify-content: center; overflow: visible; }
.sofia-gen--tarjetas_superpuestas .sg-contenedor-tarjetas { position: relative; width: clamp(280px, 90%, 800px); min-height: 300px; }
.sofia-gen--tarjetas_superpuestas .sg-tarjeta { background-color: #ffffff; border-radius: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.1); padding: 2rem; position: absolute; width: 100%; box-sizing: border-box; }
.sofia-gen--tarjetas_superpuestas .sg-principal { z-index: 2; top: 0; left: 0; }
.sofia-gen--tarjetas_superpuestas .sg-secundaria { z-index: 1; top: 2.5rem; left: 2.5rem; background-color: #f0f0f0; border: 1px solid #e0e0e0; transform: translate(2rem, 2rem); }
.sofia-gen--tarjetas_superpuestas .sg-tarjeta-titulo { font-size: clamp(1.5rem, 5vw, 2rem); color: #333; margin-bottom: 1rem; line-height: 1.2; }
.sofia-gen--tarjetas_superpuestas .sg-tarjeta-texto { font-size: clamp(0.95rem, 3vw, 1.15rem); color: #555; line-height: 1.6; }
.sofia-gen--tarjetas_superpuestas .sg-secundaria { transform: translate(1.5rem, 1.5rem); top: 2rem; left: 2rem; }
.sofia-gen--tarjetas_superpuestas .sg-contenedor-tarjetas { min-height: 350px; }

.sofia-gen--titulo_destacado_color { text-align: center; padding: 2rem 1rem; }
.sofia-gen--titulo_destacado_color .sg-titulo-principal { font-size: clamp(3rem, 10vw, 8rem); font-weight: 900; line-height: 1.1; color: var(--wp--preset--color--on-background); }
.sofia-gen--titulo_destacado_color .sg-palabra-destacada { color: var(--wp--preset--color--primary); margin: 0 0.05em; }

.sofia-gen--seccion_con_numero_fondo { position: relative; padding: 5rem 2rem; overflow: hidden; background-color: #f8f8f8; }
.sofia-gen--seccion_con_numero_fondo .sg-seccion-numero { display: flex; align-items: center; justify-content: center; min-height: 400px; }
.sofia-gen--seccion_con_numero_fondo .sg-numero-fondo { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: clamp(10rem, 25vw, 20rem); color: rgba(0, 0, 0, 0.05); font-weight: 900; z-index: 0; pointer-events: none; }
.sofia-gen--seccion_con_numero_fondo .sg-contenido-seccion { position: relative; z-index: 1; text-align: center; max-width: 800px; padding: 2rem; background-color: #ffffff; border-radius: 8px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08); }
.sofia-gen--seccion_con_numero_fondo .sg-titulo-seccion { font-size: clamp(2rem, 5vw, 3.5rem); color: #333; margin-bottom: 1.5rem; line-height: 1.2; }
.sofia-gen--seccion_con_numero_fondo .sg-parrafo-seccion { font-size: clamp(1rem, 2.5vw, 1.2rem); color: #666; line-height: 1.6; }

.sofia-gen--franja_estadisticas_hexagonos { background-color: #f7f7f7; padding: clamp(3rem, 8vw, 6rem) 0; text-align: center; }
.sofia-gen--franja_estadisticas_hexagonos .sg-titulo-seccion { font-size: clamp(2rem, 5vw, 3.5rem); color: #333; margin-bottom: clamp(2rem, 5vw, 4rem); }
.sofia-gen--franja_estadisticas_hexagonos .sg-contenedor-hexagonos { display: flex; flex-wrap: wrap; justify-content: center; gap: clamp(1rem, 3vw, 2.5rem); padding: 0 clamp(1rem, 5vw, 4rem); }
.sofia-gen--franja_estadisticas_hexagonos .sg-hexagono-wrapper { position: relative; width: clamp(120px, 20vw, 180px); height: clamp(104px, 17.32vw, 156px); margin: clamp(0.5rem, 1vw, 1rem) clamp(1rem, 1.5vw, 1.5rem); }
.sofia-gen--franja_estadisticas_hexagonos .sg-hexagono { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-color: #007bff; clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%); display: flex; flex-direction: column; justify-content: center; align-items: center; color: white; text-align: center; box-shadow: 0 8px 15px rgba(0, 0, 0, 0.2); transition: transform 0.3s ease, box-shadow 0.3s ease; transform: translateY(0); }
.sofia-gen--franja_estadisticas_hexagonos .sg-hexagono:hover { transform: translateY(-5px); box-shadow: 0 12px 20px rgba(0, 0, 0, 0.3); }
.sofia-gen--franja_estadisticas_hexagonos .sg-numero { font-size: clamp(1.8rem, 4vw, 3rem); font-weight: bold; margin: 0; line-height: 1; }
.sofia-gen--franja_estadisticas_hexagonos .sg-descripcion { font-size: clamp(0.8rem, 2vw, 1.2rem); margin-top: 0.5rem; opacity: 0.9; line-height: 1.2; padding: 0 10%; }

.sofia-gen--galeria_doble_destacado { padding: 2rem; }
.sofia-gen--galeria_doble_destacado .sg-galeria-grilla { display: grid; grid-template-columns: repeat(auto-fit, minmax(clamp(150px, 30vw, 250px), 1fr)); grid-auto-rows: 200px; gap: 1rem; }
.sofia-gen--galeria_doble_destacado .sg-galeria-item { overflow: hidden; border-radius: 8px; background-color: #eee; }
.sofia-gen--galeria_doble_destacado .sg-galeria-item-destacado { grid-column: span 2; grid-row: span 2; }
.sofia-gen--galeria_doble_destacado .sg-galeria-imagen { width: 100%; height: 100%; object-fit: cover; display: block; }
.sofia-gen--galeria_doble_destacado .sg-galeria-secundarias { display: contents; }

.sofia-gen--timeline_vertical { padding: 40px 0; }
.sofia-gen--timeline_vertical .sg-timeline { position: relative; max-width: 900px; margin: 0 auto; padding: 0 20px; }
.sofia-gen--timeline_vertical .sg-timeline-linea { position: absolute; left: 50%; top: 0; bottom: 0; width: 4px; background: #e0e0e0; transform: translateX(-50%); }
.sofia-gen--timeline_vertical .sg-timeline-eventos { list-style: none; padding: 0; margin: 0; }
.sofia-gen--timeline_vertical .sg-timeline-item { display: flex; position: relative; margin-bottom: 40px; }
.sofia-gen--timeline_vertical .sg-timeline-item:nth-child(odd) { justify-content: flex-start; }
.sofia-gen--timeline_vertical .sg-timeline-item:nth-child(even) { justify-content: flex-end; }
.sofia-gen--timeline_vertical .sg-timeline-punto { position: absolute; top: 0; left: 50%; transform: translateX(-50%); width: 20px; height: 20px; background: #6c63ff; border-radius: 50%; border: 3px solid #ffffff; z-index: 1; }
.sofia-gen--timeline_vertical .sg-timeline-contenido { background: #f8f8f8; padding: 20px; border-radius: 8px; width: calc(50% - 40px); box-shadow: 0 4px 8px rgba(0,0,0,0.1); }
.sofia-gen--timeline_vertical .sg-timeline-item:nth-child(odd) .sg-timeline-contenido { margin-right: auto; }
.sofia-gen--timeline_vertical .sg-timeline-item:nth-child(even) .sg-timeline-contenido { margin-left: auto; }
.sofia-gen--timeline_vertical .sg-timeline-fecha { display: block; font-size: 0.9em; color: #888; margin-bottom: 5px; }
.sofia-gen--timeline_vertical .sg-timeline-titulo { font-size: clamp(1.2rem, 3vw, 1.6rem); margin: 0 0 10px 0; color: #333; }
.sofia-gen--timeline_vertical .sg-timeline-descripcion { font-size: clamp(0.9rem, 2.5vw, 1rem); color: #555; line-height: 1.6; }
.sofia-gen--timeline_vertical .sg-timeline-linea { left: 20px; transform: translateX(0); }
.sofia-gen--timeline_vertical .sg-timeline-item { justify-content: flex-start !important; }
.sofia-gen--timeline_vertical .sg-timeline-punto { left: 20px; transform: translateX(-50%); }
.sofia-gen--timeline_vertical .sg-timeline-contenido { width: calc(100% - 60px); margin-left: 60px !important; margin-right: 0 !important; }

.sofia-gen--seccion_tres_beneficios { padding: clamp(2rem, 5vw, 4rem) 0; background-color: #f8f8f8; }
.sofia-gen--seccion_tres_beneficios .sg-seccion-beneficios { text-align: center; }
.sofia-gen--seccion_tres_beneficios .sg-contenedor-beneficios { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2.5rem; max-width: 1200px; margin: 0 auto; padding: 0 clamp(1rem, 3vw, 2rem); }
.sofia-gen--seccion_tres_beneficios .sg-beneficio-item { background-color: #ffffff; border-radius: 12px; padding: 2rem; box-shadow: 0 10px 20px rgba(0,0,0,0.05); transition: transform 0.3s ease, box-shadow 0.3s ease; }
.sofia-gen--seccion_tres_beneficios .sg-beneficio-item:hover { transform: translateY(-8px); box-shadow: 0 15px 30px rgba(0,0,0,0.1); }
.sofia-gen--seccion_tres_beneficios .sg-beneficio-icono { width: 64px; height: 64px; margin-bottom: 1.5rem; object-fit: contain; }
.sofia-gen--seccion_tres_beneficios .sg-beneficio-titulo { font-size: clamp(1.4rem, 2.5vw, 1.8rem); color: #333; margin-bottom: 0.8rem; font-weight: 700; line-height: 1.3; }
.sofia-gen--seccion_tres_beneficios .sg-beneficio-descripcion { font-size: clamp(1rem, 1.8vw, 1.15rem); color: #666; line-height: 1.6; }

.sofia-gen--cta_boton { padding: clamp(2rem, 8vw, 6rem) clamp(1rem, 5vw, 4rem); background-color: #f0f0f0; display: flex; justify-content: center; }
.sofia-gen--cta_boton .sg-cta-contenedor { display: flex; flex-direction: column; align-items: center; text-align: center; max-width: 800px; gap: 2rem; padding: clamp(2rem, 5vw, 4rem); background-color: #212121; color: #ffffff; border-radius: 1.5rem; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2); position: relative; overflow: hidden; }
.sofia-gen--cta_boton .sg-cta-contenedor::before { content: ''; position: absolute; inset: 0; background: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%); opacity: 0.85; z-index: 0; transform: skewY(-2deg) scale(1.05); transform-origin: top left; }
.sofia-gen--cta_boton .sg-cta-contenido, .sofia-gen--cta_boton .sg-cta-boton-wrapper { position: relative; z-index: 1; }
.sofia-gen--cta_boton .sg-cta-titulo { font-size: clamp(1.8rem, 5vw, 3.5rem); font-weight: 700; line-height: 1.2; margin-bottom: 1rem; color: #fff; text-shadow: 0 4px 8px rgba(0, 0, 0, 0.3); }
.sofia-gen--cta_boton .sg-cta-descripcion { font-size: clamp(1rem, 2.5vw, 1.25rem); line-height: 1.6; color: #e0e0e0; margin-bottom: 1.5rem; max-width: 600px; }
.sofia-gen--cta_boton .sg-cta-boton { display: inline-block; background-color: #ffb703; color: #1a1a1a; padding: 1rem 2.5rem; border-radius: 50px; text-decoration: none; font-size: clamp(1rem, 2.5vw, 1.15rem); font-weight: 600; letter-spacing: 0.05em; transition: all 0.3s ease; box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2); cursor: pointer; }
.sofia-gen--cta_boton .sg-cta-boton:hover { background-color: #fb8500; transform: translateY(-3px) scale(1.02); box-shadow: 0 15px 30px rgba(0, 0, 0, 0.3); }

.sofia-gen--equipo_moderno { padding: 4rem 2rem; background-color: #f9f9f9; }
.sofia-gen--equipo_moderno .sg-contenedor-equipo { max-width: 1200px; margin: 0 auto; text-align: center; }
.sofia-gen--equipo_moderno .sg-titulo-seccion { font-size: clamp(2rem, 5vw, 3.5rem); color: #2c3e50; margin-bottom: 1rem; position: relative; display: inline-block; }
.sofia-gen--equipo_moderno .sg-titulo-seccion::after { content: ''; display: block; width: 60%; height: 4px; background-color: #007bff; margin: 0.5rem auto 0; border-radius: 2px; }
.sofia-gen--equipo_moderno .sg-descripcion-seccion { font-size: clamp(1rem, 2.5vw, 1.25rem); color: #555; margin-bottom: 3rem; max-width: 800px; margin-left: auto; margin-right: auto; line-height: 1.6; }
.sofia-gen--equipo_moderno .sg-grilla-miembros { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 2.5rem; }
.sofia-gen--equipo_moderno .sg-tarjeta-miembro { background-color: #fff; border-radius: 15px; box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08); padding: 1.5rem; text-align: center; display: flex; flex-direction: column; align-items: center; transition: transform 0.3s ease, box-shadow 0.3s ease; overflow: hidden; }
.sofia-gen--equipo_moderno .sg-tarjeta-miembro:hover { transform: translateY(-10px); box-shadow: 0 15px 40px rgba(0, 0, 0, 0.15); }
.sofia-gen--equipo_moderno .sg-foto-marco { width: 150px; height: 150px; border-radius: 50%; overflow: hidden; margin-bottom: 1.5rem; border: 5px solid #007bff; box-shadow: 0 0 0 5px rgba(0, 123, 255, 0.3); transform: rotate(-5deg); transition: transform 0.4s ease; }
.sofia-gen--equipo_moderno .sg-tarjeta-miembro:hover .sg-foto-marco { transform: rotate(5deg) scale(1.05); }
.sofia-gen--equipo_moderno .sg-foto-miembro { width: 100%; height: 100%; object-fit: cover; object-position: center; display: block; }
.sofia-gen--equipo_moderno .sg-nombre-miembro { font-size: clamp(1.4rem, 3vw, 1.8rem); color: #2c3e50; margin-bottom: 0.5rem; font-weight: 700; }
.sofia-gen--equipo_moderno .sg-cargo-miembro { font-size: clamp(0.9rem, 2vw, 1.1rem); color: #007bff; font-weight: 600; margin-bottom: 1rem; text-transform: uppercase; letter-spacing: 0.5px; }
.sofia-gen--equipo_moderno .sg-descripcion-miembro { font-size: clamp(0.85rem, 1.8vw, 1rem); color: #666; line-height: 1.5; margin-bottom: 0; }

.sofia-gen--seccion_premium { padding: 80px 0; background-color: #f8f8f8; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; }
.sofia-gen--seccion_premium .sg-seccion-premium { position: relative; max-width: 1200px; margin: 0 auto; padding: 0 20px; }
.sofia-gen--seccion_premium .sg-contenido-principal { display: grid; grid-template-columns: 1fr 1.2fr; gap: 60px; align-items: center; }
.sofia-gen--seccion_premium .sg-texto-header { margin-bottom: 40px; }
.sofia-gen--seccion_premium .sg-titulo { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 700; color: #1a1a1a; line-height: 1.1; margin-bottom: 20px; }
.sofia-gen--seccion_premium .sg-subtitulo { font-size: clamp(1.1rem, 2.5vw, 1.6rem); color: #555; line-height: 1.5; margin-bottom: 0; }
.sofia-gen--seccion_premium .sg-imagen-area { position: relative; width: 100%; aspect-ratio: 16/10; overflow: visible; border-radius: 15px; box-shadow: 0 10px 30px rgba(0,0,0,0.15); transform: rotate(2deg) scale(0.98); transition: transform 0.3s ease; }
.sofia-gen--seccion_premium .sg-imagen-area:hover { transform: rotate(0deg) scale(1.0); }
.sofia-gen--seccion_premium .sg-imagen-principal { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; display: block; filter: brightness(0.9); }
.sofia-gen--seccion_premium .sg-detalle-destacado { position: absolute; bottom: -40px; left: -40px; background-color: #fff; padding: 30px; border-radius: 10px; box-shadow: 0 8px 25px rgba(0,0,0,0.1); width: 60%; max-width: 350px; z-index: 10; transform: rotate(-3deg); transition: transform 0.3s ease; }
.sofia-gen--seccion_premium .sg-imagen-area:hover .sg-detalle-destacado { transform: rotate(0deg); }
.sofia-gen--seccion_premium .sg-detalle-titulo { font-size: clamp(1.4rem, 3vw, 1.8rem); font-weight: 600; color: #2a2a2a; margin-bottom: 15px; line-height: 1.2; }
.sofia-gen--seccion_premium .sg-detalle-descripcion { font-size: clamp(0.9rem, 1.8vw, 1.1rem); color: #666; line-height: 1.6; }
.sofia-gen--seccion_premium .sg-contenido-principal { grid-template-columns: 1fr; gap: 40px; }
.sofia-gen--seccion_premium .sg-texto-header { text-align: center; margin-bottom: 20px; }
.sofia-gen--seccion_premium .sg-imagen-area { transform: none; }
.sofia-gen--seccion_premium .sg-detalle-destacado { position: relative; bottom: auto; left: auto; margin-top: 40px; width: 80%; max-width: none; transform: none; text-align: center; margin-left: auto; margin-right: auto; }
.sofia-gen--seccion_premium .sg-imagen-area:hover { transform: none; }
.sofia-gen--seccion_premium .sg-imagen-area:hover .sg-detalle-destacado { transform: none; }
